INSERT INTO `v1_0d733b39c1b4f200ecde636d692b961d65fd6243bd3e5ac7dc3edea76b5ec890` VALUES (6011, "マコトさん？\nどうかしましたか？\n何やら不穏な気配を\n感じ取ったのですが", 129911, 0, 6, 0.8, 6, 0, 0, 11, 1);
